--============================================================--HỆTHỐNGQUẢNLÝPHÒNGKHÁMVÀĐẶTLỊCHKHÁMBỆNH--DatabaseSchema(MySQL8.0)-Tốiưu&hợplýhơntừschemabạngửi--✅Mụctiêutốiưu:--1)Tránhtrùngdữliệungười(Bệnhnhân/BácsĩdùngchungNguoiDung)--2)ĐặtlịchtheoDATETIME(chặntrùnggiờchuẩn,dễmởrộng)--3)ĐơnthuốctáchHeader/Detail--4)Indextheoquerythựctế+ràngbuộcdữliệutốthơn--============================================================--TạoDatabaseCREATEDATABASEIFNOTEXISTSQuanLyPhongKhamCHARACTERSETutf8mb4COLLATEutf8mb4_unicode_ci;USEQuanLyPhongKham;--(Tuỳchọn)Khipháttriển:xoábảngtheothứtựFKđểtạolạiSETFOREIGN_KEY_CHECKS=0;DROPVIEWIFEXISTSv_thong_ke_lich_kham_bac_si;DROPVIEWIFEXISTSv_lich_kham_chi_tiet;DROPVIEWIFEXISTSv_bac_si_chuyen_khoa;DROPTABLEIFEXISTSDonThuocChiTiet;DROPTABLEIFEXISTSDonThuoc;DROPTABLEIFEXISTSHoSoKhamBenh;DROPTABLEIFEXISTSThongBao;DROPTABLEIFEXISTSNhatKyHoatDong;DROPTABLEIFEXISTSLichKham;DROPTABLEIFEXISTSLichLamViecBacSi;DROPTABLEIFEXISTSBenhNhan;DROPTABLEIFEXISTSBacSiChuyenKhoa;DROPTABLEIFEXISTSBacSi;DROPTABLEIFEXISTSChuyenKhoa;DROPTABLEIFEXISTSTaiKhoan;DROPTABLEIFEXISTSNguoiDung;SETFOREIGN_KEY_CHECKS=1;--============================================================--1.NGUOI_DUNG(Thôngtincánhânchung:dùngchocảBácsĩ/Lễtân/Admin/Bệnhnhân)--============================================================CREATETABLENguoiDung(NguoiDungIdINTPRIMARYKEYAUTO_INCREMENT,HoTenVARCHAR(100)NOTNULL,GioiTinhENUM('Nam','Nu','Khac')DEFAULT'Khac',DienThoaiVARCHAR(20),EmailVARCHAR(100),DiaChiTEXT,ThanhPhoVARCHAR(50),NgaySinhDATE,CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,--IndextheotracứuthườnggặpINDEXidx_nd_ho_ten(HoTen),INDEXidx_nd_dien_thoai(DienThoai),INDEXidx_nd_email(Email))ENGINE=InnoDB;--============================================================--2.TAI_KHOAN(Tàikhoảnhệthống-phânquyềnnộibộ)--Ghichú:bệnhnhâncóthểcó/khôngcótàikhoản;nếumuốnbệnhnhânđăngnhập,--bạncóthểtạothêmVaiTro'BenhNhan'hoặctạobảngTaiKhoanBenhNhanriêng.--============================================================CREATETABLETaiKhoan(TaiKhoanIdINTPRIMARYKEYAUTO_INCREMENT,NguoiDungIdINTNOTNULLUNIQUE,TenDangNhapVARCHAR(50)UNIQUENOTNULL,MatKhauHashVARCHAR(255)NOTNULL,VaiTroENUM('QuanTri','LeTan','BacSi')NOTNULL,TrangThaiENUM('HoatDong','KhongHoatDong')DEFAULT'HoatDong',CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,FOREIGNKEY(NguoiDungId)REFERENCESNguoiDung(NguoiDungId)ONDELETECASCADE,INDEXidx_tk_vai_tro(VaiTro),INDEXidx_tk_trang_thai(TrangThai))ENGINE=InnoDB;--============================================================--3.CHUYEN_KHOA--============================================================CREATETABLEChuyenKhoa(ChuyenKhoaIdINTPRIMARYKEYAUTO_INCREMENT,TenChuyenKhoaVARCHAR(100)NOTNULLUNIQUE,MoTaTEXT,TrangThaiENUM('HoatDong','KhongHoatDong')DEFAULT'HoatDong',CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,INDEXidx_ck_ten(TenChuyenKhoa),INDEXidx_ck_trang_thai(TrangThai))ENGINE=InnoDB;--============================================================--4.BAC_SI(BácsĩgắnvớiNguoiDung)--============================================================CREATETABLEBacSi(BacSiIdINTPRIMARYKEYAUTO_INCREMENT,NguoiDungIdINTNOTNULLUNIQUE,SoChungChiVARCHAR(50)UNIQUENOTNULL,CapHocVanVARCHAR(100),NamKinhNghiemINT,TieuSuTEXT,TrangThaiENUM('HoatDong','KhongHoatDong','NghiPhep')DEFAULT'HoatDong',CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,FOREIGNKEY(NguoiDungId)REFERENCESNguoiDung(NguoiDungId)ONDELETECASCADE,INDEXidx_bs_so_chung_chi(SoChungChi),INDEXidx_bs_trang_thai(TrangThai))ENGINE=InnoDB;--============================================================--5.BAC_SI_CHUYEN_KHOA(N-N)--============================================================CREATETABLEBacSiChuyenKhoa(BacSiChuyenKhoaIdINTPRIMARYKEYAUTO_INCREMENT,BacSiIdINTNOTNULL,ChuyenKhoaIdINTNOTNULL,LaChuyenMonChinhBOOLEANDEFAULTFALSE,CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,FOREIGNKEY(BacSiId)REFERENCESBacSi(BacSiId)ONDELETECASCADE,FOREIGNKEY(ChuyenKhoaId)REFERENCESChuyenKhoa(ChuyenKhoaId)ONDELETECASCADE,UNIQUEKEYuq_bacsi_chuyenkhoa(BacSiId,ChuyenKhoaId),INDEXidx_bsck_chuyen_khoa(ChuyenKhoaId))ENGINE=InnoDB;--============================================================--6.BENH_NHAN--✅Tốiưu:BệnhnhâncũngdùngNguoiDunglàmthôngtincánhân(khôngbịtrùngdữliệu)--============================================================CREATETABLEBenhNhan(BenhNhanIdINTPRIMARYKEYAUTO_INCREMENT,NguoiDungIdINTNOTNULLUNIQUE,MaBenhNhanVARCHAR(20)UNIQUENOTNULL,--ThôngtinriêngbệnhnhânTienSuBenhLyTEXT,DiUngTEXT,GhiChuTEXT,TrangThaiENUM('HoatDong','KhongHoatDong')DEFAULT'HoatDong',CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,FOREIGNKEY(NguoiDungId)REFERENCESNguoiDung(NguoiDungId)ONDELETECASCADE,INDEXidx_bn_ma(MaBenhNhan),INDEXidx_bn_trang_thai(TrangThai))ENGINE=InnoDB;--============================================================--7.LICH_LAM_VIEC_BAC_SI--✅Giữca(Sang/Chieu/Toi)đểdễquảnlýUI--✅CóGioBatDau/GioKetThuc+SlotMinutesđểhệthốngtạoslotgiờ--============================================================CREATETABLELichLamViecBacSi(LichLamViecIdINTPRIMARYKEYAUTO_INCREMENT,BacSiIdINTNOTNULL,NgayLamViecDATENOTNULL,CaLamENUM('Sang','Chieu','Toi')NOTNULL,GioBatDauTIMENOTNULL,GioKetThucTIMENOTNULL,SlotMinutesINTNOTNULLDEFAULT15,--độdài1slotkhám(phút)SoBenhNhanToiDaINTNOTNULLDEFAULT10,TrangThaiENUM('HoatDong','Huy')DEFAULT'HoatDong',CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,FOREIGNKEY(BacSiId)REFERENCESBacSi(BacSiId)ONDELETECASCADE,UNIQUEKEYuq_bs_ngay_ca(BacSiId,NgayLamViec,CaLam),INDEXidx_llv_bs_ngay(BacSiId,NgayLamViec),INDEXidx_llv_ngay_trang_thai(NgayLamViec,TrangThai))ENGINE=InnoDB;--============================================================--8.LICH_KHAM--✅Tốiưulớn:dùngDATETIMEthaychoCaKham+GioKhamnullable--->chặntrùnggiờchuẩn,dễthốngkê,dễnhắclịch--============================================================CREATETABLELichKham(LichKhamIdINTPRIMARYKEYAUTO_INCREMENT,MaLichKhamVARCHAR(20)UNIQUENOTNULL,BenhNhanIdINTNOTNULL,BacSiIdINTNOTNULL,ChuyenKhoaIdINTNOTNULL,ThoiGianBatDauDATETIMENOTNULL,ThoiGianKetThucDATETIMENULL,--cóthểtínhtheoSlotMinutesTrieuChungTEXT,TrangThaiENUM('ChoXacNhan','DaXacNhan','DaKham','DaHuy')DEFAULT'ChoXacNhan',LyDoHuyTEXT,GhiChuTEXT,TaoBoiINTNULL,XacNhanBoiINTNULL,HuyBoiINTNULL,CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,ThoiGianXacNhanTIMESTAMPNULL,ThoiGianHuyTIMESTAMPNULL,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,FOREIGNKEY(BenhNhanId)REFERENCESBenhNhan(BenhNhanId)ONDELETECASCADE,FOREIGNKEY(BacSiId)REFERENCESBacSi(BacSiId)ONDELETERESTRICT,FOREIGNKEY(ChuyenKhoaId)REFERENCESChuyenKhoa(ChuyenKhoaId)ONDELETERESTRICT,FOREIGNKEY(TaoBoi)REFERENCESTaiKhoan(TaiKhoanId)ONDELETESETNULL,FOREIGNKEY(XacNhanBoi)REFERENCESTaiKhoan(TaiKhoanId)ONDELETESETNULL,FOREIGNKEY(HuyBoi)REFERENCESTaiKhoan(TaiKhoanId)ONDELETESETNULL,--ChặntrùnglịchtheogiờUNIQUEKEYuq_bs_time(BacSiId,ThoiGianBatDau),UNIQUEKEYuq_bn_time(BenhNhanId,ThoiGianBatDau),--IndexcholọcdanhsáchINDEXidx_lk_bs_time(BacSiId,ThoiGianBatDau),INDEXidx_lk_bn_time(BenhNhanId,ThoiGianBatDau),INDEXidx_lk_ck_time(ChuyenKhoaId,ThoiGianBatDau),INDEXidx_lk_trang_thai(TrangThai),INDEXidx_lk_time_trang_thai(ThoiGianBatDau,TrangThai),INDEXidx_lk_created_at(CreatedAt),INDEXidx_lk_thoi_gian_huy(ThoiGianHuy))ENGINE=InnoDB;--============================================================--9.HO_SO_KHAM_BENH--✅1lịchkhám->tốiđa1hồsơ(UNIQUELichKhamId)--============================================================CREATETABLEHoSoKhamBenh(HoSoIdINTPRIMARYKEYAUTO_INCREMENT,MaHoSoVARCHAR(20)UNIQUENOTNULL,LichKhamIdINTNOTNULLUNIQUE,BenhNhanIdINTNOTNULL,BacSiIdINTNOTNULL,TrieuChungTEXTNOTNULL,ChanDoanTEXTNOTNULL,KeHoachDieuTriTEXT,KetLuanTEXT,GhiChuTEXT,NgayKhamDATETIMENOTNULL,--lấytừlịchkhámhoặcthờiđiểmtạohồsơCreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,UpdatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMPONUPDATECURRENT_TIMESTAMP,FOREIGNKEY(LichKhamId)REFERENCESLichKham(LichKhamId)ONDELETECASCADE,FOREIGNKEY(BenhNhanId)REFERENCESBenhNhan(BenhNhanId)ONDELETECASCADE,FOREIGNKEY(BacSiId)REFERENCESBacSi(BacSiId)ONDELETERESTRICT,INDEXidx_hs_bn_ngay(BenhNhanId,NgayKham),INDEXidx_hs_bs_ngay(BacSiId,NgayKham),INDEXidx_hs_ngay(NgayKham))ENGINE=InnoDB;--============================================================--10.DON_THUOC(Header)+DON_THUOC_CHI_TIET(Detail)--✅Táchchuẩnđểsaunàythêmmetadatadễ--============================================================CREATETABLEDonThuoc(DonThuocIdINTPRIMARYKEYAUTO_INCREMENT,MaDonThuocVARCHAR(20)UNIQUENOTNULL,HoSoIdINTNOTNULL,GhiChuTEXT,CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,FOREIGNKEY(HoSoId)REFERENCESHoSoKhamBenh(HoSoId)ONDELETECASCADE,UNIQUEKEYuq_donthuoc_hoso(HoSoId),INDEXidx_dt_hoso(HoSoId))ENGINE=InnoDB;CREATETABLEDonThuocChiTiet(DonThuocChiTietIdINTPRIMARYKEYAUTO_INCREMENT,DonThuocIdINTNOTNULL,TenThuocVARCHAR(100)NOTNULL,LieuLuongVARCHAR(50),SoLuongINT,DonViVARCHAR(20),HuongDanSuDungTEXT,ThoiGianDungVARCHAR(50),CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,FOREIGNKEY(DonThuocId)REFERENCESDonThuoc(DonThuocId)ONDELETECASCADE,INDEXidx_dtct_donthuoc(DonThuocId),INDEXidx_dtct_tenthuoc(TenThuoc))ENGINE=InnoDB;--============================================================--11.THONG_BAO--✅Indextheouse-case:lấychưađọctheotàikhoản,sắpxếpmớinhất--============================================================CREATETABLEThongBao(ThongBaoIdINTPRIMARYKEYAUTO_INCREMENT,TaiKhoanIdINTNOTNULL,LichKhamIdINTNULL,LoaiThongBaoENUM('NhacLich','LichDaXacNhan','LichDaHuy','LichDaKham','CanhBao')DEFAULT'CanhBao',TieuDeVARCHAR(200),NoiDungTEXTNOTNULL,DaDocBOOLEANDEFAULTFALSE,CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,DocLucTIMESTAMPNULL,FOREIGNKEY(TaiKhoanId)REFERENCESTaiKhoan(TaiKhoanId)ONDELETECASCADE,FOREIGNKEY(LichKhamId)REFERENCESLichKham(LichKhamId)ONDELETESETNULL,INDEXidx_tb_tk_dadoc_created(TaiKhoanId,DaDoc,CreatedAt),INDEXidx_tb_created_at(CreatedAt))ENGINE=InnoDB;--============================================================--12.NHAT_KY_HOAT_DONG(AuditLog)--============================================================CREATETABLENhatKyHoatDong(NhatKyIdINTPRIMARYKEYAUTO_INCREMENT,TaiKhoanIdINTNULL,HanhDongVARCHAR(100)NOTNULL,LoaiEntityVARCHAR(50),EntityIdINT,GiaTriCuJSON,GiaTriMoiJSON,DiaChiIpVARCHAR(45),CreatedAtTIMESTAMPDEFAULTCURRENT_TIMESTAMP,FOREIGNKEY(TaiKhoanId)REFERENCESTaiKhoan(TaiKhoanId)ONDELETESETNULL,INDEXidx_nk_tk_created(TaiKhoanId,CreatedAt),INDEXidx_nk_entity(LoaiEntity,EntityId),INDEXidx_nk_created(CreatedAt))ENGINE=InnoDB;--============================================================--VIEWS--============================================================--View:DanhsáchbácsĩvớichuyênkhoaCREATEVIEWv_bac_si_chuyen_khoaASSELECTbs.BacSiId,nd.HoTen,nd.DienThoai,nd.Email,bs.SoChungChi,bs.CapHocVan,bs.NamKinhNghiem,GROUP_CONCAT(ck.TenChuyenKhoaORDERBYck.TenChuyenKhoaSEPARATOR',')ASchuyen_khoa,bs.TrangThaiFROMBacSibsJOINNguoiDungndONbs.NguoiDungId=nd.NguoiDungIdLEFTJOINBacSiChuyenKhoabsckONbs.BacSiId=bsck.BacSiIdLEFTJOINChuyenKhoackONbsck.ChuyenKhoaId=ck.ChuyenKhoaIdGROUPBYbs.BacSiId;--View:DanhsáchlịchkhámchitiếtCREATEVIEWv_lich_kham_chi_tietASSELECTlk.LichKhamId,lk.MaLichKham,bn.MaBenhNhan,nd_bn.HoTenASten_benh_nhan,nd_bs.HoTenASten_bac_si,ck.TenChuyenKhoa,lk.ThoiGianBatDau,lk.ThoiGianKetThuc,lk.TrieuChung,lk.TrangThaiFROMLichKhamlkJOINBenhNhanbnONlk.BenhNhanId=bn.BenhNhanIdJOINNguoiDungnd_bnONbn.NguoiDungId=nd_bn.NguoiDungIdJOINBacSibsONlk.BacSiId=bs.BacSiIdJOINNguoiDungnd_bsONbs.NguoiDungId=nd_bs.NguoiDungIdJOINChuyenKhoackONlk.ChuyenKhoaId=ck.ChuyenKhoaId;--View:ThốngkêlịchkhámtheobácsĩCREATEVIEWv_thong_ke_lich_kham_bac_siASSELECTbs.BacSiId,nd.HoTenASten_bac_si,COUNT(lk.LichKhamId)AStong_lich_kham,SUM(CASEWHENlk.TrangThai='DaKham'THEN1ELSE0END)ASlich_da_kham,SUM(CASEWHENlk.TrangThai='DaHuy'THEN1ELSE0END)ASlich_da_huy,SUM(CASEWHENlk.TrangThai='ChoXacNhan'THEN1ELSE0END)ASlich_cho_xac_nhan,SUM(CASEWHENlk.TrangThai='DaXacNhan'THEN1ELSE0END)ASlich_da_xac_nhanFROMBacSibsJOINNguoiDungndONbs.NguoiDungId=nd.NguoiDungIdLEFTJOINLichKhamlkONbs.BacSiId=lk.BacSiIdGROUPBYbs.BacSiId;--============================================================--DỮLIỆUMẪU(Cậpnhậttheoschemamới)--============================================================--ChuyênkhoaINSERTINTOChuyenKhoa(TenChuyenKhoa,MoTa)VALUES('TimMach','Chuyenkhoavebenhtimvamachmau'),('HoHap','Chuyenkhoavebenhhohap'),('TieuHoa','Chuyenkhoavebenhtieuhoa'),('NgoaiDa','Chuyenkhoavebenhdalieu'),('NhiKhoa','Chuyenkhoavebenhnhi');--Ngườidùng(nộibộ+bệnhnhânđềunằmởđây)INSERTINTONguoiDung(HoTen,GioiTinh,DienThoai,Email,ThanhPho,NgaySinh,DiaChi)VALUES('QuanTriVien','Nam','0900000001','admin@clinic.com','TPHCM','1990-01-01','Quan1'),('NguyenThiLeTan','Nu','0900000002','receptionist@clinic.com','TPHCM','1992-02-02','Quan1'),('TS.TranVanA','Nam','0900000003','doctor1@clinic.com','TPHCM','1980-03-03','Quan3'),('ThS.LeThiB','Nu','0900000004','doctor2@clinic.com','TPHCM','1985-04-04','Quan5'),('TS.PhamVanC','Nam','0900000005','doctor3@clinic.com','TPHCM','1978-05-05','Quan7'),('NguyenVanX','Nam','0912345678','patient1@email.com','TPHCM','1990-05-15','Quan1'),('TranThiY','Nu','0912345679','patient2@email.com','TPHCM','1985-08-20','Quan2'),('PhamVanZ','Nam','0912345680','patient3@email.com','TPHCM','1995-12-10','Quan3');--TàikhoảnnộibộINSERTINTOTaiKhoan(NguoiDungId,TenDangNhap,MatKhauHash,VaiTro,TrangThai)VALUES(1,'admin','$2b$10$hashedpassword1','QuanTri','HoatDong'),(2,'receptionist1','$2b$10$hashedpassword2','LeTan','HoatDong'),(3,'doctor1','$2b$10$hashedpassword3','BacSi','HoatDong'),(4,'doctor2','$2b$10$hashedpassword4','BacSi','HoatDong'),(5,'doctor3','$2b$10$hashedpassword5','BacSi','HoatDong');--BácsĩINSERTINTOBacSi(NguoiDungId,SoChungChi,CapHocVan,NamKinhNghiem,TieuSu,TrangThai)VALUES(3,'LIC001','TienSiYhoc'